__NUXT_JSONP__("/it/stay", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{details:{slug:"it",pageTitle:"Alloggi | Mentor Language Institute",pageDescription:"MLI collabora con U.S. Support Services Inc che fornisce alloggi per studenti",title:"Alloggi",subtitle:["MLI collabora con U.S. Support Services Inc che fornisce alloggi per studenti \u003Cbr \u002F\u003EPer maggiori dettagli, visita \u003Ca href=\"www.usssinc.net\u002Fit\" target=\"_blank\"\u003Ewww.usssinc.net\u002Fit\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Gli studenti hanno la possibilità di scegliere di alloggiare in uno dei nostri dormitori o di aderire al Programma Homestay.",types:[{title:"Dormitori",description:["Disponiamo di 40 camere nei nostri dormitori. Hai l'opportunità di conoscere e condividere esperienze con altri studenti internazionali. Ti consigliamo di alloggiare nel dormitorio se hai un budget da rispettare."],lists:["\u003Cb\u003ECamere\u003C\u002Fb\u003E : Private (Individuali), condivise (due persone) o quadruple(4 persone)","\u003Cb\u003EPasti\u003C\u002Fb\u003E : Non sono compresi i pasti. È disponibile una cucina interamente accessoriata.","\u003Cb\u003EPrivacy\u003C\u002Fb\u003E : c'è più privacy nei dormitori che nelle Homestay. I dormitori hanno dei regolamenti da rispettare.","\u003Cb\u003E Raggiungere la scuola\u003C\u002Fb\u003E : circa 20 minuti a piedi e con l'autobus."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Prezzi dei dormitori",table:{tableMaxCol:4,title:"Placement Fee* : $200\u003Cbr \u002F\u003E Se il giovane ha meno di 18 anni, l'affitto sarà superiore di circa il 10% rispetto al prezzo per una persona di età superiore ai 18 anni.",thead:[b,c,"Shared (2 people)","Quad (4 people)"],tbody:[[d,a,a,a],[e,"$550","$410",a],[f,"$1,100","$820","$600"],[g,"$1,650","$1,230","$900"],[h,"$2,200","$1,640","$1,200"],[i,"$4,160","$2,960","$2,160"],[j,"$6,240","$4,440","$3,240"]]},notes:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out."]}]},{title:"Homestay",description:["Gli studenti che scelgono di vivere con una famiglia ospitante nell'ambito del programma Homestay sono alla ricerca di un'atmosfera sicura, accogliente e confortevole in cui poter esercitare le proprie abilità linguistiche. È anche un'ottima opportunità per imparare costumi e tradizioni americane e valori familiari."],lists:["\u003Cb\u003ECamere\u003C\u002Fb\u003E : Private (Individual)","\u003Cb\u003EPasti\u003C\u002Fb\u003E : 2 pasti al giorno(colazione e cena)","\u003Cb\u003EPrivacy\u003C\u002Fb\u003E : vanno rispettate le regole richieste dalle diverse famiglie ospitanti.","\u003Cb\u003ERaggiungere la scuola\u003C\u002Fb\u003E : 30-45 minuti con l'autobus"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Prezzi programma Homestay",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E Se il giovane ha meno di 18 anni, l'affitto sarà superiore di circa il 10% rispetto al prezzo per una persona di età superiore ai 18 anni.",thead:[b,c,"Shared***"],tbody:[[d,a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]},notes:["*Placement fee is a one time payment. It's not refundable.\u003Cbr \u002F\u003E**Security deposit will be refunded after students have moved out.\u003Cbr \u002F\u003E***If you request a homestay shared room, \u003Cspan class=\"rmarker\"\u003Eyou must apply with another person.\u003C\u002Fspan\u003E"]}]}],comments:{title:"Opinioni del nostro staff",description:["Non è semplice trovare un alloggio appena si arriva in città, specialmente se si è studenti internazionali senza un Social Security Number (SSN) e una storia creditizia. Molti posti richiedono entrambi SSN e storia creditizia per essere idonei ad affittare un apartamento o una stanza. Per questo vi consigliamo di considerare le soluzioni di alloggi da noi offerte almeno per il primo paio di mesi.","※L'alloggio è fornito da U.S. Support Service Inc. o altre agenzie."]},dir:"\u002Fstay",path:"\u002Fstay\u002Fit",extension:".json",createdAt:"2026-10-22T16:31:31.098Z",updatedAt:"2025-05-26T12:06:27.919Z"}}],fetch:{},mutations:void 0}}("$300","","Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks")));